4	/// `Interleave` is an iterator that interleaves elements of iterators
5	/// `i` and `j` in one continuous iterator. This struct is created by
6	/// the [`interleave()`] method on [`IndexedParallelIterator`]
7	///
8	/// [`interleave()`]: IndexedParallelIterator::interleave()
9	#[must_use = "iterator adaptors are lazy and do nothing unless consumed"]
10	#[derive(Debug, Clone)]
11	pub struct Interleave<I, J> {
12	    i: I,
13	    j: J,
14	}
15	
16	impl<I, J> Interleave<I, J> {
17	    /// Creates a new `Interleave` iterator
18	    pub(super) fn new(i: I, j: J) -> Self {
19	        Interleave { i, j }
20	    }
21	}
22	
23	impl<I, J> ParallelIterator for Interleave<I, J>
24	where
25	    I: IndexedParallelIterator,
26	    J: IndexedParallelIterator<Item = I::Item>,
27	{
28	    type Item = I::Item;
29	
30	    fn drive_unindexed<C>(self, consumer: C) -> C::Result
31	    where
