4	/// `TakeAny` is an iterator that iterates over `n` elements from anywhere in `I`.
5	/// This struct is created by the [`take_any()`] method on [`ParallelIterator`]
6	///
7	/// [`take_any()`]: ParallelIterator::take_any()
8	#[must_use = "iterator adaptors are lazy and do nothing unless consumed"]
9	#[derive(Clone, Debug)]
10	pub struct TakeAny<I> {
11	    base: I,
12	    count: usize,
13	}
14	
15	impl<I> TakeAny<I> {
16	    /// Creates a new `TakeAny` iterator.
17	    pub(super) fn new(base: I, count: usize) -> Self {
18	        TakeAny { base, count }
19	    }
20	}
21	
22	impl<I> ParallelIterator for TakeAny<I>
23	where
24	    I: ParallelIterator,
25	{
26	    type Item = I::Item;
27	
28	    fn drive_unindexed<C>(self, consumer: C) -> C::Result
29	    where
30	        C: UnindexedConsumer<Self::Item>,
31	    {
32	        let consumer1 = TakeAnyConsumer {
33	            base: consumer,
34	            count: &AtomicUsize::new(self.count),
35	        };
36	        self.base.drive_unindexed(consumer1)
37	    }
38	}
39	
40	// ////////////////////////////////////////////////////////////////////////
41	// Consumer implementation
42	
43	struct TakeAnyConsumer<'f, C> {
44	    base: C,
45	    count: &'f AtomicUsize,
46	}
47	
48	impl<'f, T, C> Consumer<T> for TakeAnyConsumer<'f, C>
49	where
50	    C: Consumer<T>,
51	    T: Send,
52	{
53	    type Folder = TakeAnyFolder<'f, C::Folder>;
54	    type Reducer = C::Reducer;
55	    type Result = C::Result;
56	
57	    fn split_at(self, index: usize) -> (Self, Self, Self::Reducer) {
58	        let (left, right, reducer) = self.base.split_at(index);
59	        (
60	            TakeAnyConsumer { base: left, ..self },
61	            TakeAnyConsumer {
62	                base: right,
63	                ..self
64	            },
65	            reducer,
66	        )
67	    }
68	
69	    fn into_folder(self) -> Self::Folder {
70	        TakeAnyFolder {
71	            base: self.base.into_folder(),
72	            count: self.count,
73	        }
74	    }
75	
76	    fn full(&self) -> bool {
77	        self.count.load(Ordering::Relaxed) == 0 || self.base.full()
78	    }
79	}
80	
81	impl<'f, T, C> UnindexedConsumer<T> for TakeAnyConsumer<'f, C>
82	where
83	    C: UnindexedConsumer<T>,
84	    T: Send,
85	{
86	    fn split_off_left(&self) -> Self {
87	        TakeAnyConsumer {
88	            base: self.base.split_off_left(),
89	            ..*self
90	        }
91	    }
92	
93	    fn to_reducer(&self) -> Self::Reducer {
94	        self.base.to_reducer()
95	    }
96	}
97	
98	struct TakeAnyFolder<'f, C> {
99	    base: C,
100	    count: &'f AtomicUsize,
101	}
102	
103	fn checked_decrement(u: &AtomicUsize) -> bool {
104	    #[allow(deprecated, reason = "TODO (MSRV 1.95): use try_update")]
105	    u.fetch_update(Ordering::Relaxed, Ordering::Relaxed, |u| u.checked_sub(1))
106	        .is_ok()
107	}
108	
109	impl<'f, T, C> Folder<T> for TakeAnyFolder<'f, C>
110	where
111	    C: Folder<T>,
112	{
113	    type Result = C::Result;
114	
115	    fn consume(mut self, item: T) -> Self {
116	        if checked_decrement(self.count) {
117	            self.base = self.base.consume(item);
118	        }
119	        self
120	    }
121	
122	    fn consume_iter<I>(mut self, iter: I) -> Self
123	    where
124	        I: IntoIterator<Item = T>,
125	    {
126	        self.base = self.base.consume_iter(
127	            iter.into_iter()
128	                .take_while(move |_| checked_decrement(self.count)),
129	        );
130	        self
131	    }
132	
133	    fn complete(self) -> C::Result {
134	        self.base.complete()
135	    }
136	
137	    fn full(&self) -> bool {
138	        self.count.load(Ordering::Relaxed) == 0 || self.base.full()
139	    }
140	}
