5	/// `Intersperse` is an iterator that inserts a particular item between each
6	/// item of the adapted iterator.  This struct is created by the
7	/// [`intersperse()`] method on [`ParallelIterator`]
8	///
9	/// [`intersperse()`]: ParallelIterator::intersperse()
10	#[must_use = "iterator adaptors are lazy and do nothing unless consumed"]
11	#[derive(Clone, Debug)]
12	pub struct Intersperse<I>
13	where
14	    I: ParallelIterator,
15	{
16	    base: I,
17	    item: I::Item,
18	}
19	
20	impl<I> Intersperse<I>
21	where
22	    I: ParallelIterator<Item: Clone>,
23	{
24	    /// Creates a new `Intersperse` iterator
25	    pub(super) fn new(base: I, item: I::Item) -> Self {
26	        Intersperse { base, item }
27	    }
28	}
29	
30	impl<I> ParallelIterator for Intersperse<I>
31	where
32	    I: ParallelIterator<Item: Clone>,
33	{
34	    type Item = I::Item;
35	
36	    fn drive_unindexed<C>(self, consumer: C) -> C::Result
37	    where
38	        C: UnindexedConsumer<I::Item>,
39	    {
40	        let consumer1 = IntersperseConsumer::new(consumer, self.item);
41	        self.base.drive_unindexed(consumer1)
42	    }
43	
44	    fn opt_len(&self) -> Option<usize> {
45	        match self.base.opt_len()? {
46	            0 => Some(0),
47	            len => len.checked_add(len - 1),
48	        }
49	    }
50	}
51	
52	impl<I> IndexedParallelIterator for Intersperse<I>
53	where
54	    I: IndexedParallelIterator<Item: Clone>,
55	{
56	    fn drive<C>(self, consumer: C) -> C::Result
57	    where
58	        C: Consumer<Self::Item>,
59	    {
60	        let consumer1 = IntersperseConsumer::new(consumer, self.item);
61	        self.base.drive(consumer1)
62	    }
63	
64	    fn len(&self) -> usize {
65	        let len = self.base.len();
66	        if len > 0 {
67	            len.checked_add(len - 1).expect("overflow")
68	        } else {
69	            0
70	        }
71	    }
72	
73	    fn with_producer<CB>(self, callback: CB) -> CB::Output
74	    where
75	        CB: ProducerCallback<Self::Item>,
76	    {
77	        let len = self.len();
78	        return self.base.with_producer(Callback {
79	            callback,
80	            item: self.item,
81	            len,
82	        });
83	
84	        struct Callback<CB, T> {
85	            callback: CB,
86	            item: T,
87	            len: usize,
88	        }
89	
90	        impl<T, CB> ProducerCallback<T> for Callback<CB, T>
91	        where
92	            CB: ProducerCallback<T>,
93	            T: Clone + Send,
94	        {
95	            type Output = CB::Output;
96	
97	            fn callback<P>(self, base: P) -> CB::Output
98	            where
99	                P: Producer<Item = T>,
100	            {
101	                let producer = IntersperseProducer::new(base, self.item, self.len);
102	                self.callback.callback(producer)
103	            }
104	        }
105	    }
106	}
107	
108	struct IntersperseProducer<P>
109	where
110	    P: Producer,
111	{
112	    base: P,
113	    item: P::Item,
114	    len: usize,
115	    clone_first: bool,
116	}
117	
118	impl<P> IntersperseProducer<P>
119	where
120	    P: Producer,
121	{
122	    fn new(base: P, item: P::Item, len: usize) -> Self {
123	        IntersperseProducer {
124	            base,
125	            item,
126	            len,
127	            clone_first: false,
128	        }
129	    }
130	}
131	
132	impl<P> Producer for IntersperseProducer<P>
133	where
134	    P: Producer<Item: Clone + Send>,
135	{
136	    type Item = P::Item;
137	    type IntoIter = IntersperseIter<P::IntoIter>;
138	
139	    fn into_iter(self) -> Self::IntoIter {
140	        IntersperseIter {
141	            base: self.base.into_iter().fuse(),
142	            item: self.item,
143	            clone_first: self.len > 0 && self.clone_first,
144	
145	            // If there's more than one item, then even lengths end the opposite
146	            // of how they started with respect to interspersed clones.
147	            clone_last: self.len > 1 && ((self.len & 1 == 0) ^ self.clone_first),
148	        }
149	    }
150	
151	    fn min_len(&self) -> usize {
152	        self.base.min_len()
153	    }
154	    fn max_len(&self) -> usize {
155	        self.base.max_len()
156	    }
157	
158	    fn split_at(self, index: usize) -> (Self, Self) {
159	        debug_assert!(index <= self.len);
160	
161	        // The left needs half of the items from the base producer, and the
162	        // other half will be our interspersed item.  If we're not leading with
163	        // a cloned item, then we need to round up the base number of items,
164	        // otherwise round down.
165	        let base_index = (index + !self.clone_first as usize) / 2;
166	        let (left_base, right_base) = self.base.split_at(base_index);
167	
168	        let left = IntersperseProducer {
169	            base: left_base,
170	            item: self.item.clone(),
171	            len: index,
172	            clone_first: self.clone_first,
173	        };
174	
175	        let right = IntersperseProducer {
176	            base: right_base,
177	            item: self.item,
178	            len: self.len - index,
179	
180	            // If the index is odd, the right side toggles `clone_first`.
181	            clone_first: (index & 1 == 1) ^ self.clone_first,
182	        };
183	
184	        (left, right)
185	    }
186	
187	    fn fold_with<F>(self, folder: F) -> F
188	    where
189	        F: Folder<Self::Item>,
190	    {
191	        let folder1 = IntersperseFolder {
192	            base: folder,
193	            item: self.item,
194	            clone_first: self.clone_first,
195	        };
196	        self.base.fold_with(folder1).base
197	    }
198	}
199	
200	struct IntersperseIter<I>
201	where
202	    I: Iterator,
203	{
204	    base: Fuse<I>,
205	    item: I::Item,
206	    clone_first: bool,
207	    clone_last: bool,
208	}
209	
210	impl<I> Iterator for IntersperseIter<I>
211	where
212	    I: DoubleEndedIterator<Item: Clone> + ExactSizeIterator,
213	{
214	    type Item = I::Item;
215	
216	    fn next(&mut self) -> Option<Self::Item> {
217	        if self.clone_first {
218	            self.clone_first = false;
219	            Some(self.item.clone())
220	        } else if let next @ Some(_) = self.base.next() {
221	            // If there are any items left, we'll need another clone in front.
222	            self.clone_first = self.base.len() != 0;
223	            next
224	        } else if self.clone_last {
225	            self.clone_last = false;
226	            Some(self.item.clone())
227	        } else {
228	            None
229	        }
230	    }
231	
232	    fn size_hint(&self) -> (usize, Option<usize>) {
233	        let len = self.len();
234	        (len, Some(len))
235	    }
236	}
237	
238	impl<I> DoubleEndedIterator for IntersperseIter<I>
239	where
240	    I: DoubleEndedIterator<Item: Clone> + ExactSizeIterator,
241	{
242	    fn next_back(&mut self) -> Option<Self::Item> {
243	        if self.clone_last {
244	            self.clone_last = false;
245	            Some(self.item.clone())
246	        } else if let next_back @ Some(_) = self.base.next_back() {
247	            // If there are any items left, we'll need another clone in back.
248	            self.clone_last = self.base.len() != 0;
249	            next_back
250	        } else if self.clone_first {
251	            self.clone_first = false;
252	            Some(self.item.clone())
253	        } else {
254	            None
255	        }
256	    }
257	}
258	
259	impl<I> ExactSizeIterator for IntersperseIter<I>
260	where
261	    I: DoubleEndedIterator<Item: Clone> + ExactSizeIterator,
262	{
263	    fn len(&self) -> usize {
264	        let len = self.base.len();
265	        len + len.saturating_sub(1) + self.clone_first as usize + self.clone_last as usize
266	    }
267	}
268	
269	struct IntersperseConsumer<C, T> {
270	    base: C,
271	    item: T,
272	    clone_first: Cell<bool>,
273	}
274	
275	impl<C, T> IntersperseConsumer<C, T>
276	where
277	    C: Consumer<T>,
278	{
279	    fn new(base: C, item: T) -> Self {
280	        IntersperseConsumer {
281	            base,
282	            item,
283	            clone_first: false.into(),
284	        }
285	    }
286	}
287	
288	impl<C, T> Consumer<T> for IntersperseConsumer<C, T>
289	where
290	    C: Consumer<T>,
291	    T: Clone + Send,
292	{
293	    type Folder = IntersperseFolder<C::Folder, T>;
294	    type Reducer = C::Reducer;
295	    type Result = C::Result;
296	
297	    fn split_at(mut self, index: usize) -> (Self, Self, Self::Reducer) {
298	        // We'll feed twice as many items to the base consumer, except if we're
299	        // not currently leading with a cloned item, then it's one less.
300	        let base_index = index + index.saturating_sub(!self.clone_first.get() as usize);
301	        let (left, right, reducer) = self.base.split_at(base_index);
302	
303	        let right = IntersperseConsumer {
304	            base: right,
305	            item: self.item.clone(),
306	            clone_first: true.into(),
307	        };
308	        self.base = left;
309	        (self, right, reducer)
310	    }
311	
312	    fn into_folder(self) -> Self::Folder {
313	        IntersperseFolder {
314	            base: self.base.into_folder(),
315	            item: self.item,
316	            clone_first: self.clone_first.get(),
317	        }
318	    }
319	
320	    fn full(&self) -> bool {
321	        self.base.full()
322	    }
323	}
324	
325	impl<C, T> UnindexedConsumer<T> for IntersperseConsumer<C, T>
326	where
327	    C: UnindexedConsumer<T>,
328	    T: Clone + Send,
329	{
330	    fn split_off_left(&self) -> Self {
331	        let left = IntersperseConsumer {
332	            base: self.base.split_off_left(),
333	            item: self.item.clone(),
334	            clone_first: self.clone_first.clone(),
335	        };
336	        self.clone_first.set(true);
337	        left
338	    }
339	
340	    fn to_reducer(&self) -> Self::Reducer {
341	        self.base.to_reducer()
342	    }
343	}
344	
345	struct IntersperseFolder<C, T> {
346	    base: C,
347	    item: T,
348	    clone_first: bool,
349	}
350	
351	impl<C, T> Folder<T> for IntersperseFolder<C, T>
352	where
353	    C: Folder<T>,
354	    T: Clone,
355	{
356	    type Result = C::Result;
357	
358	    fn consume(mut self, item: T) -> Self {
359	        if self.clone_first {
360	            self.base = self.base.consume(self.item.clone());
361	            if self.base.full() {
362	                return self;
363	            }
364	        } else {
365	            self.clone_first = true;
366	        }
367	        self.base = self.base.consume(item);
368	        self
369	    }
370	
371	    fn consume_iter<I>(self, iter: I) -> Self
372	    where
373	        I: IntoIterator<Item = T>,
374	    {
